<?php
$mysqli = new mysqli('localhost', 'u3509947_default', 'h4tu4Y2BBjeXQTq2', 'u3509947_default');
$mysqli->set_charset('utf8');
$tracks = $mysqli->query("SELECT * FROM tracks ORDER BY created DESC")->fetch_all(MYSQLI_ASSOC);
$videos = $mysqli->query("SELECT * FROM videos ORDER BY created DESC")->fetch_all(MYSQLI_ASSOC);
$concerts = $mysqli->query("SELECT * FROM concerts ORDER BY date ASC")->fetch_all(MYSQLI_ASSOC);
$gallery = $mysqli->query("SELECT * FROM gallery ORDER BY created DESC")->fetch_all(MYSQLI_ASSOC);
$settings = $mysqli->query("SELECT * FROM settings")->fetch_all(MYSQLI_ASSOC);
$settings = array_column($settings, 'value', 'key');
$about = $settings['about_text'] ?? '';
$stats = [
  'num1' => $settings['stat1'] ?? '150+',
  'label1' => $settings['stat1label'] ?? 'ПЕСЕН',
  'num2' => $settings['stat2'] ?? '15',
  'label2' => $settings['stat2label'] ?? 'ЛЕТ НА СЦЕНЕ',
  'num3' => $settings['stat3'] ?? '3',
  'label3' => $settings['stat3label'] ?? 'СЕЗОН ГОЛОС'
];
$accent = $settings['accent'] ?? '#cc0000';
$bg = $settings['bg'] ?? '#000000';
$text = $settings['text'] ?? '#ffffff';
?>
<!DOCTYPE html>
<html lang="ru"><head><meta charset="UTF-8"><meta name="viewport" content="width=device-width, initial-scale=1.0"><title>РУСЛАН СИЛИН</title><link href="https://fonts.googleapis.com/css2?family=Oswald:wght@300;400;700&family=Roboto+Mono:wght@300;700&display=swap" rel="stylesheet"><style>
:root{--accent:<?=$accent?>;--bg:<?=$bg?>;--text:<?=$text?>}
*{margin:0;padding:0;box-sizing:border-box}body{background:var(--bg);color:var(--text);font-family:'Oswald',sans-serif;line-height:1.4;text-transform:uppercase;letter-spacing:1.5px;overflow-x:hidden}.menu{position:fixed;top:0;left:0;width:100%;padding:25px 40px;z-index:999;display:flex;justify-content:space-between;align-items:center;backdrop-filter:blur(8px);background:rgba(0,0,0,0.4);transition:0.3s;border-bottom:1px solid var(--accent)}.menu.hidden{transform:translateY(-100%)}.logo{display:flex;align-items:center}.logo img{height:100px;width:auto;object-fit:contain}.nav{display:flex;gap:50px}.nav a{color:var(--text);text-decoration:none;font-size:14px;letter-spacing:4px;font-weight:300;transition:0.3s}.nav a:hover{color:var(--accent)}.hero{min-height:100vh;display:flex;align-items:center;justify-content:center;position:relative;overflow:hidden}.hero-bg{position:absolute;top:0;left:0;width:100%;height:100%;background:url('/images/hero.jpg') center/cover;filter:grayscale(0.4) contrast(1.3) brightness(0.35);transform:scale(1.05)}.hero-overlay{position:absolute;top:0;left:0;width:100%;height:100%;background:radial-gradient(circle at center,transparent 0%,var(--bg) 100%)}.hero-content{position:relative;z-index:10;text-align:center}.glitch{font-size:clamp(4rem,12vw,10rem);font-weight:700;line-height:1.1;letter-spacing:18px;text-shadow:0.05em 0 0 var(--accent);animation:glitch 1.5s infinite}@keyframes glitch{0%,100%{text-shadow:0.05em 0 0 var(--accent)}25%{text-shadow:-0.05em -0.025em 0 var(--accent)}50%{text-shadow:0.025em 0.05em 0 var(--accent)}75%{text-shadow:-0.025em 0 0 var(--accent)}}.hero-sub{font-family:'Roboto Mono',monospace;font-size:15px;letter-spacing:12px;opacity:0.8;margin:30px 0}.hero-line{width:180px;height:2px;background:var(--accent);margin:40px auto;transform:skewX(-25deg)}.marquee{background:rgba(10,10,10,0.5);border-top:1px solid #1a1a1a;border-bottom:1px solid #1a1a1a;padding:18px 0;overflow:hidden;white-space:nowrap}.marquee-content{display:inline-block;animation:marquee 22s linear infinite;font-family:'Roboto Mono',monospace;font-size:13px;letter-spacing:5px;color:#888}@keyframes marquee{0%{transform:translateX(0)}100%{transform:translateX(-50%)}}.section{max-width:1400px;margin:0 auto;padding:120px 40px}.section-title{font-size:clamp(2.8rem,6vw,5rem);font-weight:700;margin-bottom:70px;position:relative;letter-spacing:4px}.about-grid{display:grid;grid-template-columns:1fr 1fr;gap:60px;align-items:start}.about-text{font-family:'Roboto Mono',monospace;font-size:15px;line-height:1.8;text-transform:none;color:#bbb;padding:30px;background:rgba(10,10,10,0.6);border:1px solid #1a1a1a}.about-stats{display:grid;grid-template-columns:repeat(3,1fr);gap:25px}.stat-item{text-align:center;padding:30px 20px;border:1px solid #1a1a1a;background:rgba(0,0,0,0.5)}.stat-number{font-size:3.5rem;font-weight:700;color:var(--accent)}.stat-label{font-size:11px;letter-spacing:4px;margin-top:10px;opacity:0.7}.gallery-grid{display:grid;grid-template-columns:repeat(4,1fr);gap:15px}.gallery-item{aspect-ratio:1/1;border:1px solid #1a1a1a;overflow:hidden}.gallery-item img{width:100%;height:100%;object-fit:cover;filter:grayscale(0.6) contrast(1.2);transition:0.6s}.gallery-item:hover img{filter:grayscale(0) contrast(1.1);transform:scale(1.05)}.grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(350px,1fr));gap:50px}.card{background:#050505;border:1px solid #111;transition:0.5s}.card:hover{transform:translateY(-15px);border-color:var(--accent)}.card-img{height:300px;overflow:hidden}.card-img img{width:100%;height:100%;object-fit:cover;filter:grayscale(0.5) contrast(1.2);transition:0.8s}.card:hover .card-img img{filter:grayscale(0) contrast(1);transform:scale(1.05)}.card-content{padding:30px}.card-title{font-size:24px;margin-bottom:15px;letter-spacing:3px}.btn{padding:16px 40px;background:transparent;border:2px solid var(--accent);color:var(--text);text-decoration:none;font-weight:700;letter-spacing:5px;transition:0.3s;display:inline-block;cursor:pointer}.btn:hover{background:var(--accent)}.concert-list{border:1px solid #1a1a1a}.concert-item{display:flex;justify-content:space-between;align-items:center;padding:25px 30px;border-bottom:1px solid #1a1a1a;transition:0.2s}.concert-item:hover{background:#0a0a0a;padding-left:40px}.concert-date{font-size:1.8rem;font-weight:700;color:var(--accent);min-width:130px}.concert-city{font-size:1.3rem}.newsletter{background:#0a0a0a;border:1px solid #1a1a1a;padding:50px;text-align:center;margin-top:80px}.newsletter h3{font-size:2.2rem;margin-bottom:15px}.newsletter-form{display:flex;max-width:550px;margin:30px auto 0;gap:8px}.newsletter-form input{flex:1;padding:16px;background:#000;border:1px solid #1a1a1a;color:var(--text);font-family:'Roboto Mono',monospace;text-transform:uppercase}.newsletter-form button{padding:16px 35px;background:var(--accent);border:0;color:var(--text);font-weight:600;letter-spacing:3px;cursor:pointer}footer{padding:50px;text-align:center;border-top:1px solid #1a1a1a;margin-top:80px}.modal-overlay{position:fixed;top:0;left:0;width:100%;height:100%;background:rgba(0,0,0,0.9);z-index:10001;display:none;align-items:center;justify-content:center}.modal-overlay.active{display:flex}.modal{background:#0a0a0a;border:1px solid var(--accent);padding:40px;max-width:500px;width:90%;text-align:center}.modal input{width:100%;padding:16px;margin:10px 0;background:#000;border:1px solid #1a1a1a;color:var(--text);font-family:'Roboto Mono',monospace}.modal .btn{margin-top:15px;width:100%}.lightbox{position:fixed;top:0;left:0;width:100%;height:100%;background:rgba(0,0,0,0.95);z-index:20000;display:none;align-items:center;justify-content:center}.lightbox.active{display:flex}.lightbox img{max-width:95%;max-height:95%;object-fit:contain}.lightbox-close{position:absolute;top:20px;right:30px;color:var(--accent);font-size:3rem;cursor:pointer}
</style></head><body>
<nav class="menu"><a href="/" class="logo"><img src="/images/logo.png" alt="СИЛИН"></a><div class="nav"><a href="#about">ОБ АРТИСТЕ</a><a href="#gallery">ГАЛЕРЕЯ</a><a href="#music">МУЗЫКА</a><a href="#video">ВИДЕО</a><a href="#concerts">МЕРОПРИЯТИЯ</a></div></nav>
<section class="hero"><div class="hero-bg"></div><div class="hero-overlay"></div><div class="hero-content"><div class="glitch">РУСЛАН СИЛИН</div><div class="hero-sub">КОМПОЗИТОР // АВТОР // ИСПОЛНИТЕЛЬ</div><div class="hero-line"></div></div></section>
<div class="marquee"><div class="marquee-content">/// МОЛИТВА /// УЧАСТНИК ШОУ ГОЛОС /// САУНДТРЕКИ К КИНО /// ТЕЛЕКАНАЛ СПАС /// /// МОЛИТВА /// УЧАСТНИК ШОУ ГОЛОС /// САУНДТРЕКИ К КИНО /// ТЕЛЕКАНАЛ СПАС ///</div></div>
<section class="section" id="about"><h2 class="section-title">// ОБ АРТИСТЕ //</h2><div class="about-grid"><div class="about-text"><?=nl2br(htmlspecialchars($about))?><br><br><a href="#" class="btn" onclick="openModal()">ЗАКАЗАТЬ ПЕСНЮ</a></div><div class="about-stats"><div class="stat-item"><div class="stat-number"><?=$stats['num1']?></div><div class="stat-label"><?=$stats['label1']?></div></div><div class="stat-item"><div class="stat-number"><?=$stats['num2']?></div><div class="stat-label"><?=$stats['label2']?></div></div><div class="stat-item"><div class="stat-number"><?=$stats['num3']?></div><div class="stat-label"><?=$stats['label3']?></div></div></div></div></section>
<section class="section" id="gallery"><h2 class="section-title">// ГАЛЕРЕЯ //</h2><div class="gallery-grid"><?php foreach($gallery as $g):?><div class="gallery-item"><img src="/uploads/<?=$g['file']?>" alt="<?=$g['title']?>"></div><?php endforeach;?></div></section>
<section class="section" id="music"><h2 class="section-title">// МУЗЫКА //</h2><div class="grid"><?php foreach($tracks as $t):?><div class="card"><div class="card-img"><?=$t['cover']?'<img src="/uploads/'.$t['cover'].'">':'<div style="height:100%;background:#0a0a0a"></div>'?></div><div class="card-content"><div class="card-title"><?=$t['title']?></div><div style="color:var(--accent);font-size:0.8rem;letter-spacing:2px;margin-bottom:15px"><?=$t['description']?></div><a href="<?=$t['file']?>" target="_blank" class="btn">СЛУШАТЬ</a></div></div><?php endforeach;?></div></section>
<section class="section" id="video"><h2 class="section-title">// ВИДЕО //</h2><div class="grid"><?php foreach($videos as $v): preg_match('/v=([^&]+)/', $v['youtube_url'], $m); $id = $m[1] ?? '';?><div class="card"><div style="position:relative;padding-bottom:56.25%;height:0"><iframe src="https://www.youtube.com/embed/<?=$id?>" style="position:absolute;top:0;left:0;width:100%;height:100%" allowfullscreen></iframe></div><div class="card-content"><div class="card-title"><?=$v['title']?></div></div></div><?php endforeach;?></div></section>
<section class="section" id="concerts"><h2 class="section-title">// МЕРОПРИЯТИЯ //</h2><div class="concert-list"><?php foreach($concerts as $c):?><div class="concert-item"><div><span class="concert-date"><?=$c['date']?> <?=$c['time']?></span><span class="concert-city"><?=$c['city']?><?=$c['venue']?', '.$c['venue']:''?></span><?php if($c['description']):?><div style="font-size:11px;opacity:0.5;margin-top:5px;text-transform:none"><?=$c['description']?></div><?php endif;?></div><?php if($c['banner']):?><img src="/uploads/<?=$c['banner']?>" style="max-width:100%;height:auto;max-height:200px;cursor:pointer" onclick="lightbox('/uploads/<?=$c['banner']?>')"><?php elseif($c['ticket_url']):?><a href="<?=$c['ticket_url']?>" class="btn">БИЛЕТЫ</a><?php endif;?></div><?php endforeach;?></div></section>
<section class="section"><div class="newsletter"><h3>ПОДПИШИСЬ НА НОВОСТИ</h3><form class="newsletter-form" id="subscribe-form"><input type="email" name="email" placeholder="ВАШ EMAIL" required><button type="submit">ПОДПИСАТЬСЯ</button></form><p id="subscribe-message" style="display:none;margin-top:15px;color:var(--accent)"></p></div></section>
<footer><p>РУСЛАН СИЛИН // ОФИЦИАЛЬНЫЙ САЙТ // <a href="/admin" style="color:#666">[ADMIN]</a></p></footer>
<div class="modal-overlay" id="modal-overlay"><div class="modal"><h2>ЗАКАЗАТЬ ПЕСНЮ</h2><form id="order-form"><input type="text" name="name" placeholder="ВАШЕ ИМЯ" required><input type="email" name="email" placeholder="EMAIL" required><input type="tel" name="phone" placeholder="ТЕЛЕФОН" required><button type="submit" class="btn">ОТПРАВИТЬ</button></form><p id="modal-message" style="margin-top:15px;color:var(--accent)"></p></div></div>
<div class="lightbox" id="lightbox" onclick="this.classList.remove('active')"><span class="lightbox-close">&times;</span><img src="" id="lightbox-img"></div>
<script>
function openModal(){document.getElementById('modal-overlay').classList.add('active')}
document.getElementById('modal-overlay').addEventListener('click',function(e){if(e.target===this)this.classList.remove('active')});
function lightbox(src){document.getElementById('lightbox-img').src=src;document.getElementById('lightbox').classList.add('active')}
document.getElementById('subscribe-form').addEventListener('submit',async function(e){
  e.preventDefault();
  var msg=document.getElementById('subscribe-message');
  var email=this.querySelector('[name=email]').value;
  try{
    var res=await fetch('/api/subscribe',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({email})});
    if(res.ok){msg.style.display='block';msg.textContent='ВЫ ПОДПИСАНЫ';this.reset()}
  }catch(err){msg.style.display='block';msg.textContent='ОШИБКА'}
});
document.getElementById('order-form').addEventListener('submit',async function(e){
  e.preventDefault();
  var msg=document.getElementById('modal-message');
  var name=this.querySelector('[name=name]').value;
  var email=this.querySelector('[name=email]').value;
  var phone=this.querySelector('[name=phone]').value;
  try{
    var res=await fetch('/api/order',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({name,email,phone})});
    if(res.ok){msg.textContent='ЗАЯВКА ОТПРАВЛЕНА!';this.reset();setTimeout(function(){document.getElementById('modal-overlay').classList.remove('active')},2000)}
  }catch(err){msg.textContent='ОШИБКА'}
});
</script>
</body></html>
